"""Browser hit-testing catches real ancestor clipping beyond rectangular overflow checks."""
JS=r'''let shape_clipped=[];{let tws=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);while(tws.nextNode()){let n=tws.currentNode,e=n.parentElement,t=n.textContent;if(!t.trim()||['SCRIPT','STYLE'].includes(e.tagName))continue;let st=getComputedStyle(e);if(st.display==='none'||st.visibility==='hidden'||!e.getClientRects().length)continue;let clips=[];for(let a=e;a&&a!==root.parentElement;a=a.parentElement){let c=getComputedStyle(a);if(c.clipPath!=='none'||(['hidden','clip'].includes(c.overflowX)||['hidden','clip'].includes(c.overflowY))&&[c.borderTopLeftRadius,c.borderTopRightRadius,c.borderBottomLeftRadius,c.borderBottomRightRadius].some(x=>parseFloat(x)>0))clips.push(a)}if(!clips.length)continue;let bad=[];for(let k=0;k<t.length;k++){if(!t[k].trim())continue;let rr=document.createRange();rr.setStart(n,k);rr.setEnd(n,k+1);let r=rr.getBoundingClientRect();if(r.width<.5||r.height<.5)continue;let x=r.left+r.width/2,y=r.top+r.height/2,hit=document.elementFromPoint(x,y);if(hit&&clips.some(c=>!c.contains(hit)))bad.push({char:t[k],offset:k,point:[x,y],hit:hit.className})}if(bad.length)shape_clipped.push({text:t.trim().slice(0,180),characters:bad})}}'''
